package com.example.data.model

// Generated by scripts/build_exercise_library.mjs from free-exercise-db (public domain, Unlicense).
// Do not edit by hand; edit the script and regenerate.

internal data class Template(
    /** Id of the exercise in free-exercise-db; its two photos live in composeResources/files/exercises. */
    val imageId: String,
    val name: String,
    val reps: String,
    val description: String,
    val tip: String,
    val steps: List<String>,
    val muscles: String
)

internal val exerciseLibrary: Map<MuscleGroup, List<Template>> = mapOf(
        MuscleGroup.CHEST to listOf(
            Template("Pushups", "Pushups", "10-15 controlled reps", "Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Next, lower yourself downward until your chest almost touches the floor as you inhale.", "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.", listOf("Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.", "Next, lower yourself downward until your chest almost touches the floor as you inhale.", "Now breathe out and press your upper body back up to the starting position while squeezing your chest.", "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."), "Chest, Shoulders, Triceps"),
            Template("Push-Up_Wide", "Push-Up Wide", "10-15 controlled reps", "With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight.", "After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions.", listOf("With your hands wide apart, support your body on your toes and hands in a plank position. Your elbows should be extended and your body straight. Do not allow your hips to sag. This will be your starting position.", "To begin, allow the elbows to flex, lowering your chest to the floor as you inhale.", "Using your pectoral muscles, press your upper body back up to the starting position by extending the elbows. Exhale as you perform this step.", "After pausing at the contracted position, repeat the movement for the prescribed amount of repetitions."), "Chest, Abdominals, Shoulders, Triceps"),
            Template("Incline_Push-Up", "Incline Push-Up", "10-15 controlled reps", "Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.", "Push body up until arms are extended. Repeat.", listOf("Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width.", "Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms.", "Push body up until arms are extended. Repeat."), "Chest, Shoulders, Triceps"),
            Template("Incline_Push-Up_Wide", "Incline Push-Up Wide", "10-15 controlled reps", "Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands on the bar, with your hands wider than shoulder width.", "Return to the starting position by extending the elbows, pressing yourself back up.", listOf("Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.", "Place your hands on the bar, with your hands wider than shoulder width.", "Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position.", "Keeping your body straight, lower your chest to the bar by bending the arms.", "Return to the starting position by extending the elbows, pressing yourself back up."), "Chest, Abdominals, Shoulders, Triceps"),
            Template("Isometric_Chest_Squeezes", "Isometric Chest Squeezes", "Hold steady", "While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).", "Rest for the recommended amount of time and repeat.", listOf("While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso).", "Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction.", "Hold for the recommended number of seconds.", "Now release the tension slowly.", "Rest for the recommended amount of time and repeat."), "Chest, Shoulders, Triceps"),
            Template("Push-Ups_With_Feet_Elevated", "Push-Ups With Feet Elevated", "10-15 controlled reps", "Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length. Place your toes on top of a flat bench.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.", listOf("Lie on the floor face down and place your hands about 36 inches apart from each other holding your torso up at arms length.", "Place your toes on top of a flat bench. This will allow your body to be elevated. Note: The higher the elevation of the flat bench, the higher the resistance of the exercise is.", "Lower yourself until your chest almost touches the floor as you inhale.", "Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."), "Chest, Shoulders, Triceps"),
            Template("Pushups_Close_and_Wide_Hand_Positions", "Pushups (Close and Wide Hand Positions)", "10-15 controlled reps", "Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.", listOf("Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.", "Lower yourself until your chest almost touches the floor as you inhale.", "Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."), "Chest, Shoulders, Triceps"),
            Template("Clock_Push-Up", "Clock Push-Up", "10-15 controlled reps", "Move into a prone position on the floor, supporting your weight on your hands and toes. Your arms should be fully extended with the hands around shoulder width.", "Return to the starting position and repeat the exercise, working all the way around until you are back where you started.", listOf("Move into a prone position on the floor, supporting your weight on your hands and toes.", "Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position.", "Descend by flexing at the elbow, lowering your chest toward the ground.", "At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to \"jump\" 12-18 inches to one side.", "As you accelerate up, move your outside foot away from your direction of travel. Leaving the ground, shift your body about 30 degrees for the next repetition.", "Return to the starting position and repeat the exercise, working all the way around until you are back where you started."), "Chest, Shoulders, Triceps"),
            Template("Push_Up_to_Side_Plank", "Push Up to Side Plank", "10-15 controlled reps", "Get into pushup position on the toes with your hands just outside of shoulder width. Perform a pushup by allowing the elbows to flex.", "Repeat the series, alternating each side, for 10 or more reps.", listOf("Get into pushup position on the toes with your hands just outside of shoulder width.", "Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.", "Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.", "Lower the arm back to the floor for another pushup and then twist to the other side.", "Repeat the series, alternating each side, for 10 or more reps."), "Chest, Abdominals, Shoulders, Triceps")
        ),
        MuscleGroup.ABS to listOf(
            Template("Crunches", "Crunches", "10-15 controlled reps", "Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.", "Repeat for the recommended amount of repetitions.", listOf("Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch.", "Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don't lock your fingers behind your head.", "While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders off the floor.", "Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. At the top of the movement, contract your abdominals hard and keep the contraction for a second. Tip: Focus on slow, controlled movement - don't cheat yourself by using momentum.", "After the one second contraction, begin to come down slowly again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."), "Abdominals"),
            Template("Plank", "Plank", "Hold steady", "Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.", "Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.", listOf("Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.", "Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."), "Abdominals"),
            Template("Russian_Twist", "Russian Twist", "10-15 controlled reps", "Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.", "Repeat for the recommended amount of repetitions.", listOf("Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.", "Elevate your upper body so that it creates an imaginary V-shape with your thighs. Your arms should be fully extended in front of you perpendicular to your torso and with the hands clasped. This is the starting position.", "Twist your torso to the right side until your arms are parallel with the floor while breathing out.", "Hold the contraction for a second and move back to the starting position while breathing out. Now move to the opposite side performing the same techniques you applied to the right side.", "Repeat for the recommended amount of repetitions."), "Abdominals, Lower back"),
            Template("Dead_Bug", "Dead Bug", "Hold steady", "Begin lying on your back with your hands extended above you toward the ceiling. Bring your feet, knees, and hips up to 90 degrees.", "Repeat on the opposite side, alternating until the set is complete.", listOf("Begin lying on your back with your hands extended above you toward the ceiling.", "Bring your feet, knees, and hips up to 90 degrees.", "Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position.", "Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground.", "Maintain the position of your lumbar and pelvis as you perform the movement, as your back is going to want to arch.", "Stay tight and return the working leg to the starting position.", "Repeat on the opposite side, alternating until the set is complete."), "Abdominals"),
            Template("Reverse_Crunch", "Reverse Crunch", "10-15 controlled reps", "Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.", "Repeat for the recommended amount of repetitions.", listOf("Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.", "Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.", "While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.", "Hold the contraction for a second and move your legs back to the starting position while exhaling.", "Repeat for the recommended amount of repetitions."), "Abdominals"),
            Template("Air_Bike", "Air Bike", "Steady, fast pace", "Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head.", "Continue alternating in this manner until all of the recommended repetitions for each side have been completed.", listOf("Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.", "Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.", "Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.", "Go back to the initial position as you breathe in.", "Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.", "Continue alternating in this manner until all of the recommended repetitions for each side have been completed."), "Abdominals"),
            Template("Flutter_Kicks", "Flutter Kicks", "Steady, fast pace", "On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge. Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips.", "Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement.", listOf("On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge.", "Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position.", "Start the movement by lifting the left leg higher than the right leg.", "Then lower the left leg as you lift the right leg.", "Continue alternating in this manner (as though you are doing a flutter kick in water) until you have done the recommended amount of repetitions for each leg. Make sure that you keep a controlled movement at all times. Tip: You will breathe normally as you perform this movement."), "Glutes, Hamstrings"),
            Template("Side_Bridge", "Side Bridge", "Hold steady", "Move slowly and with control through the full range.", "Breathe steadily and stop if you feel pain.", listOf("Move slowly and with control through the full range."), "Abdominals, Shoulders"),
            Template("Sit-Up", "Sit-Up", "10-15 controlled reps", "Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.", "Repeat for the recommended amount of repetitions.", listOf("Lie down on the floor placing your feet either under something that will not move or by having a partner hold them. Your legs should be bent at the knees.", "Place your hands behind your head and lock them together by clasping your fingers. This is the starting position.", "Elevate your upper body so that it creates an imaginary V-shape with your thighs. Breathe out when performing this part of the exercise.", "Once you feel the contraction for a second, lower your upper body back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions."), "Abdominals"),
            Template("Oblique_Crunches_-_On_The_Floor", "Oblique Crunches - On The Floor", "10-15 controlled reps", "Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.", "Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise.", listOf("Start out by lying on your right side with your legs lying on top of each other. Make sure your knees are bent a little bit.", "Place your left hand behind your head.", "Once you are in this set position, begin by moving your left elbow up as you would perform a normal crunch except this time the main emphasis is on your obliques.", "Crunch as high as you can, hold the contraction for a second and then slowly drop back down into the starting position.", "Remember to breathe in during the eccentric (lowering) part of the exercise and to breathe out during the concentric (elevation) part of the exercise."), "Abdominals"),
            Template("Cross-Body_Crunch", "Cross-Body Crunch", "10-15 controlled reps", "Lie flat on your back and bend your knees about 60 degrees. Keep your feet flat on the floor and place your hands loosely behind your head.", "Continue alternating in this manner until all prescribed repetitions are done.", listOf("Lie flat on your back and bend your knees about 60 degrees.", "Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position.", "Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember that the key is to contract the abs as you perform the movement; not just to move the elbow.", "Now go back down to the starting position as you inhale and repeat with the left elbow and the right knee.", "Continue alternating in this manner until all prescribed repetitions are done."), "Abdominals"),
            Template("Bent-Knee_Hip_Raise", "Bent-Knee Hip Raise", "10-15 controlled reps", "Lay flat on the floor with your arms next to your sides. Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.", "Repeat for the recommended amount of repetitions.", listOf("Lay flat on the floor with your arms next to your sides.", "Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches.", "Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest.", "Squeeze your abs at the top of the movement for a second and then return to the starting position slowly as you breathe in. Tip: Maintain a controlled motion at all times.", "Repeat for the recommended amount of repetitions."), "Abdominals")
        ),
        MuscleGroup.ARMS to listOf(
            Template("Bench_Dips", "Bench Dips", "10-15 controlled reps", "For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width.", "Repeat for the recommended amount of repetitions.", listOf("For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.", "Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.", "Using your triceps to bring your torso up again, lift yourself back to the starting position.", "Repeat for the recommended amount of repetitions."), "Triceps, Chest, Shoulders"),
            Template("Push-Ups_-_Close_Triceps_Position", "Push-Ups - Close Triceps Position", "10-15 controlled reps", "Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms' length.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.", listOf("Lie on the floor face down and place your hands closer than shoulder width for a close hand position. Make sure that you are holding your torso up at arms' length.", "Lower yourself until your chest almost touches the floor as you inhale.", "Using your triceps and some of your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."), "Triceps, Chest, Shoulders"),
            Template("Incline_Push-Up_Close-Grip", "Incline Push-Up Close-Grip", "10-15 controlled reps", "Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands next to one another on the bar.", "Return to the starting position by extending the elbows, pressing yourself back up.", listOf("Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height.", "Place your hands next to one another on the bar.", "Position your feet back from the bar with arms and body straight. This will be your starting position.", "Keeping your body straight, lower your chest to the bar by bending the arms.", "Return to the starting position by extending the elbows, pressing yourself back up."), "Triceps, Chest, Shoulders"),
            Template("Standing_Towel_Triceps_Extension", "Standing Towel Triceps Extension", "10-15 controlled reps", "To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other.", "Repeat for the recommended amount of repetitions.", listOf("To begin, stand up with both arms fully extended above the head holding one end of a towel with both hands. Your elbows should be in and the arms perpendicular to the floor with the palms facing each other while your feet should be shoulder width apart from each other. This is the starting position.", "Now communicate with your partner so that he/she can grip the other side of the towel to apply resistance. Keeping your upper arms close to your head (elbows in) and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.", "Go back to the starting position by using the triceps to raise the towel. Breathe out as you perform this step.", "Repeat for the recommended amount of repetitions."), "Triceps"),
            Template("Arm_Circles", "Arm Circles", "Hold & breathe", "Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso.", "Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.", listOf("Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position.", "Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement.", "Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction."), "Shoulders, Traps"),
            Template("Pushups_Close_and_Wide_Hand_Positions", "Pushups (Close and Wide Hand Positions)", "10-15 controlled reps", "Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions.", listOf("Lie on the floor face down and body straight with your toes on the floor and the hands wider than shoulder width for a wide hand position and closer than shoulder width for a close hand position. Make sure you are holding your torso up at arms length.", "Lower yourself until your chest almost touches the floor as you inhale.", "Using your pectoral muscles, press your upper body back up to the starting position and squeeze your chest. Breathe out as you perform this step.", "After a second pause at the contracted position, repeat the movement for the prescribed amount of repetitions."), "Chest, Shoulders, Triceps"),
            Template("Push_Up_to_Side_Plank", "Push Up to Side Plank", "10-15 controlled reps", "Get into pushup position on the toes with your hands just outside of shoulder width. Perform a pushup by allowing the elbows to flex.", "Repeat the series, alternating each side, for 10 or more reps.", listOf("Get into pushup position on the toes with your hands just outside of shoulder width.", "Perform a pushup by allowing the elbows to flex. As you descend, keep your body straight.", "Do one pushup and as you come up, shift your weight on the left side of the body, twist to the side while bringing the right arm up towards the ceiling in a side plank.", "Lower the arm back to the floor for another pushup and then twist to the other side.", "Repeat the series, alternating each side, for 10 or more reps."), "Chest, Abdominals, Shoulders, Triceps"),
            Template("Triceps_Stretch", "Triceps Stretch", "Hold & breathe", "Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides.", "Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides.", listOf("Reach your hand behind your head, grasp your elbow and gently pull. Hold for 10 to 20 seconds, then switch sides."), "Triceps, Lats")
        ),
        MuscleGroup.LEGS to listOf(
            Template("Bodyweight_Squat", "Bodyweight Squat", "10-15 controlled reps", "Stand with your feet shoulder width apart. You can place your hands behind your head.", "Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.", listOf("Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.", "Begin the movement by flexing your knees and hips, sitting back with your hips.", "Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."), "Quadriceps, Glutes, Hamstrings"),
            Template("Bodyweight_Walking_Lunge", "Bodyweight Walking Lunge", "10-15 controlled reps", "Begin standing with your feet shoulder width apart and your hands on your hips. Step forward with one leg, flexing the knees to drop your hips.", "Step forward with your rear foot, repeating the lunge on the opposite leg.", listOf("Begin standing with your feet shoulder width apart and your hands on your hips.", "Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.", "Drive through the heel of your lead foot and extend both knees to raise yourself back up.", "Step forward with your rear foot, repeating the lunge on the opposite leg."), "Quadriceps, Calves, Glutes, Hamstrings"),
            Template("Butt_Lift_Bridge", "Butt Lift (Bridge)", "10-15 controlled reps", "Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width.", "Slowly go back to the starting position as you breathe in.", listOf("Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position.", "Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second.", "Slowly go back to the starting position as you breathe in."), "Glutes, Hamstrings"),
            Template("Single_Leg_Glute_Bridge", "Single Leg Glute Bridge", "10-15 controlled reps", "Lay on the floor with your feet flat and knees bent. Raise one leg off of the ground, pulling the knee to your chest.", "Extend as far as possible, pause and then return to the starting position.", listOf("Lay on the floor with your feet flat and knees bent.", "Raise one leg off of the ground, pulling the knee to your chest. This will be your starting position.", "Execute the movement by driving through the heel, extending your hip upward and raising your glutes off of the ground.", "Extend as far as possible, pause and then return to the starting position."), "Glutes, Hamstrings"),
            Template("Step-up_with_Knee_Raise", "Step-up with Knee Raise", "10-15 controlled reps", "Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.", "Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg.", listOf("Stand facing a box or bench of an appropriate height with your feet together. This will be your starting position.", "Begin the movement by stepping up, putting your left foot on the top of the bench. Extend through the hip and knee of your front leg to stand up on the box. As you stand on the box with your left leg, flex your right knee and hip, bringing your knee as high as you can.", "Reverse this motion to step down off the box, and then repeat the sequence on the opposite leg."), "Glutes, Hamstrings, Quadriceps"),
            Template("Freehand_Jump_Squat", "Freehand Jump Squat", "Steady, fast pace", "Cross your arms over your chest. With your head up and your back straight, position your feet at shoulder width.", "Repeat for the recommended amount of repetitions.", listOf("Cross your arms over your chest.", "With your head up and your back straight, position your feet at shoulder width.", "Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.", "Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.", "When you touch the floor again, immediately squat down and jump again.", "Repeat for the recommended amount of repetitions."), "Quadriceps, Calves, Glutes, Hamstrings"),
            Template("Split_Squats", "Split Squats", "Hold & breathe", "Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.", "As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg.", listOf("Being in a standing position. Jump into a split leg position, with one leg forward and one leg back, flexing the knees and lowering your hips slightly as you do so.", "As you descend, immediately reverse direction, standing back up and jumping, reversing the position of your legs. Repeat 5-10 times on each leg."), "Hamstrings, Calves, Glutes, Quadriceps"),
            Template("Glute_Kickback", "Glute Kickback", "10-15 controlled reps", "Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves.", "Continue to alternate legs until all of the recommended repetitions have been performed.", listOf("Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.", "As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 90-degree angle bend. Contract the glutes throughout this movement and hold the contraction at the top for a second. Tip: At the end of the movement the upper leg should be parallel to the floor while the calf should be perpendicular to it.", "Go back to the initial position as you inhale and now repeat with the left leg.", "Continue to alternate legs until all of the recommended repetitions have been performed."), "Glutes, Hamstrings"),
            Template("Side_Leg_Raises", "Side Leg Raises", "Hold & breathe", "Stand next to a chair, which you may hold onto as a support. Stand on one leg.", "Repeat this swinging motion 5-10 times, increasing the range of motion as you do so.", listOf("Stand next to a chair, which you may hold onto as a support. Stand on one leg. This will be your starting position.", "Keeping your leg straight, raise it as far out to the side as possible, and swing it back down, allowing it to cross the opposite leg.", "Repeat this swinging motion 5-10 times, increasing the range of motion as you do so."), "Adductors"),
            Template("Rear_Leg_Raises", "Rear Leg Raises", "Hold & breathe", "Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves.", "Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides.", listOf("Place yourself on your hands knees on an exercise mat. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position.", "Extend one leg up and behind you. The knee and hip should both extend. Repeat for 5-10 repetitions, and then switch sides."), "Quadriceps")
        ),
        MuscleGroup.BACK_SHOULDERS to listOf(
            Template("Superman", "Superman", "Hold & breathe", "To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you.", "Repeat for the recommended amount of repetitions prescribed in your program.", listOf("To begin, lie straight and face down on the floor or exercise mat. Your arms should be fully extended in front of you. This is the starting position.", "Simultaneously raise your arms, legs, and chest off of the floor and hold this contraction for 2 seconds. Tip: Squeeze your lower back to get the best results from this exercise. Remember to exhale during this movement. Note: When holding the contracted position, you should look like superman when he is flying.", "Slowly begin to lower your arms, legs and chest back down to the starting position while inhaling.", "Repeat for the recommended amount of repetitions prescribed in your program."), "Lower back, Glutes, Hamstrings"),
            Template("Cat_Stretch", "Cat Stretch", "Hold & breathe", "Position yourself on the floor on your hands and knees. Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.", "Hold for 15 seconds.", listOf("Position yourself on the floor on your hands and knees.", "Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.", "Hold for 15 seconds."), "Lower back, Middle back, Traps"),
            Template("Shoulder_Circles", "Shoulder Circles", "Hold & breathe", "With shoulders relaxed and arms resting loosely at your sides (or in your lap if you're seated), gently roll your shoulders forward, up, back, and down. Reverse direction.", "Reverse direction. You can do this exercise alternating shoulders or both at the same time.", listOf("With shoulders relaxed and arms resting loosely at your sides (or in your lap if you're seated), gently roll your shoulders forward, up, back, and down.", "Reverse direction. You can do this exercise alternating shoulders or both at the same time."), "Shoulders, Traps"),
            Template("Dynamic_Back_Stretch", "Dynamic Back Stretch", "Hold & breathe", "Stand with your feet shoulder width apart. This will be your starting position.", "Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head.", listOf("Stand with your feet shoulder width apart. This will be your starting position.", "Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head."), "Lats"),
            Template("Windmills", "Windmills", "Hold & breathe", "Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.", "Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions.", listOf("Lie on your back with your arms extended out to the sides and your legs straight. This will be your starting position.", "Lift one leg and quickly cross it over your body, attempting to touch the ground near the opposite hand.", "Return to the starting position, and repeat with the opposite leg. Continue to alternate for 10-20 repetitions."), "Abductors, Glutes, Hamstrings, Lower back"),
            Template("Torso_Rotation", "Torso Rotation", "Hold & breathe", "Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you.", "Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions.", listOf("Stand upright holding an exercise ball with both hands. Extend your arms so the ball is straight out in front of you. This will be your starting position.", "Rotate your torso to one side, keeping your eyes on the ball as you move. Now, rotate back to the opposite direction. Repeat for 10-20 repetitions."), "Abdominals"),
            Template("Round_The_World_Shoulder_Stretch", "Round The World Shoulder Stretch", "Hold & breathe", "Stand up straight with your legs together, holding a bodybar or broomstick. Hold the pole behind your hips with a wider than shoulder width grip.", "Slowly lift your arms up behind your head. Don't force it if it gets hard to lift further.", listOf("Stand up straight with your legs together, holding a bodybar or broomstick.", "Hold the pole behind your hips with a wider than shoulder width grip. Your palms should be down and your thumbs facing out.", "Slowly lift your arms up behind your head. Don't force it if it gets hard to lift further."), "Shoulders, Biceps, Chest"),
            Template("One_Half_Locust", "One Half Locust", "Hold & breathe", "Lie facedown on the floor. Put your left hand under your left hipbone to pad your hip and pubic bone.", "Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn't bother your back, you can try it with both arms and legs at the same time.", listOf("Lie facedown on the floor.", "Put your left hand under your left hipbone to pad your hip and pubic bone.", "Bend your right knee so you can hold the foot in your right hand.", "Lift the foot in the air and simultaneously lift your shoulders off the floor. This also stretches the right hip flexor and the chest and shoulders. Switch sides. If it doesn't bother your back, you can try it with both arms and legs at the same time."), "Quadriceps, Abdominals, Biceps, Chest"),
            Template("Upper_Back_Stretch", "Upper Back Stretch", "Hold & breathe", "Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward.", "Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward.", listOf("Clasp fingers together with your thumbs pointing down, round your shoulders as you reach your hands forward."), "Middle back, Middle back"),
            Template("Elbows_Back", "Elbows Back", "Hold & breathe", "Stand up straight. Place both hands on your lower back, fingers pointing downward and elbows out.", "Then gently pull your elbows back aiming to touch them together.", listOf("Stand up straight.", "Place both hands on your lower back, fingers pointing downward and elbows out.", "Then gently pull your elbows back aiming to touch them together."), "Chest, Shoulders")
        ),
        MuscleGroup.FULL_BODY to listOf(
            Template("Star_Jump", "Star Jump", "Steady, fast pace", "Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body. To initiate the move, squat down halfway and explode back up as high as possible.", "As you land, bring your limbs back in and absorb your impact through the legs.", listOf("Begin in a relaxed stance with your feet shoulder width apart and hold your arms close to the body.", "To initiate the move, squat down halfway and explode back up as high as possible. Fully extend your entire body, spreading your legs and arms away from the body.", "As you land, bring your limbs back in and absorb your impact through the legs."), "Quadriceps, Calves, Glutes, Hamstrings, Shoulders"),
            Template("Bodyweight_Squat", "Bodyweight Squat", "10-15 controlled reps", "Stand with your feet shoulder width apart. You can place your hands behind your head.", "Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.", listOf("Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position.", "Begin the movement by flexing your knees and hips, sitting back with your hips.", "Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out."), "Quadriceps, Glutes, Hamstrings"),
            Template("Pushups", "Pushups", "10-15 controlled reps", "Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Next, lower yourself downward until your chest almost touches the floor as you inhale.", "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed.", listOf("Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length.", "Next, lower yourself downward until your chest almost touches the floor as you inhale.", "Now breathe out and press your upper body back up to the starting position while squeezing your chest.", "After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions as needed."), "Chest, Shoulders, Triceps"),
            Template("Mountain_Climbers", "Mountain Climbers", "Steady, fast pace", "Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip.", "Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds.", listOf("Begin in a pushup position, with your weight supported by your hands and toes. Flexing the knee and hip, bring one leg until the knee is approximately under the hip. This will be your starting position.", "Explosively reverse the positions of your legs, extending the bent leg until the leg is straight and supported by the toe, and bringing the other foot up with the hip and knee flexed. Repeat in an alternating fashion for 20-30 seconds."), "Quadriceps, Chest, Hamstrings, Shoulders"),
            Template("Inchworm", "Inchworm", "Hold & breathe", "Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you.", "Continue walking until your feet are by hour hands, keeping your legs straight as you do so.", listOf("Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position.", "Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight.", "Keep going until your body is parallel to the ground in a pushup position.", "Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a time.", "Continue walking until your feet are by hour hands, keeping your legs straight as you do so."), "Hamstrings"),
            Template("Bodyweight_Walking_Lunge", "Bodyweight Walking Lunge", "10-15 controlled reps", "Begin standing with your feet shoulder width apart and your hands on your hips. Step forward with one leg, flexing the knees to drop your hips.", "Step forward with your rear foot, repeating the lunge on the opposite leg.", listOf("Begin standing with your feet shoulder width apart and your hands on your hips.", "Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot.", "Drive through the heel of your lead foot and extend both knees to raise yourself back up.", "Step forward with your rear foot, repeating the lunge on the opposite leg."), "Quadriceps, Calves, Glutes, Hamstrings"),
            Template("Plank", "Plank", "Hold steady", "Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.", "Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised.", listOf("Get into a prone position on the floor, supporting your weight on your toes and your forearms. Your arms are bent and directly below the shoulder.", "Keep your body straight at all times, and hold this position as long as possible. To increase difficulty, an arm or leg can be raised."), "Abdominals"),
            Template("Fast_Skipping", "Fast Skipping", "Steady, fast pace", "Start in a relaxed position with one leg slightly forward. This will be your starting position.", "Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.", listOf("Start in a relaxed position with one leg slightly forward. This will be your starting position.", "Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth.", "Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible."), "Quadriceps, Abductors, Adductors, Calves, Glutes, Hamstrings"),
            Template("Single_Leg_Butt_Kick", "Single Leg Butt Kick", "Steady, fast pace", "Begin by standing on one leg, with the bent knee raised. This will be your start position.", "Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill.", listOf("Begin by standing on one leg, with the bent knee raised. This will be your start position.", "Using a countermovement jump, take off upward by extending the hip, knee, and ankle of the grounded leg.", "Immediately flex the knee and attempt to touch your butt with the heel of your jumping leg.", "Return the leg to a partially bent position underneath the hips and land. Your opposite leg should stay in relatively the same position throughout the drill."), "Quadriceps, Calves, Hamstrings"),
            Template("Freehand_Jump_Squat", "Freehand Jump Squat", "Steady, fast pace", "Cross your arms over your chest. With your head up and your back straight, position your feet at shoulder width.", "Repeat for the recommended amount of repetitions.", listOf("Cross your arms over your chest.", "With your head up and your back straight, position your feet at shoulder width.", "Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor.", "Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement.", "When you touch the floor again, immediately squat down and jump again.", "Repeat for the recommended amount of repetitions."), "Quadriceps, Calves, Glutes, Hamstrings")
        ),
        MuscleGroup.REST to listOf(
            Template("Childs_Pose", "Child's Pose", "Hold & breathe", "Get on your hands and knees, walk your hands in front of you. Lower your buttocks down to sit on your heels.", "Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems.", listOf("Get on your hands and knees, walk your hands in front of you.", "Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine.", "Once you settle onto your heels, bring your hands next to your feet and relax. \"breathe\" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems."), "Lower back, Glutes, Middle back"),
            Template("Cat_Stretch", "Cat Stretch", "Hold & breathe", "Position yourself on the floor on your hands and knees. Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.", "Hold for 15 seconds.", listOf("Position yourself on the floor on your hands and knees.", "Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop.", "Hold for 15 seconds."), "Lower back, Middle back, Traps"),
            Template("Hamstring_Stretch", "Hamstring Stretch", "Hold & breathe", "Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.", "Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg.", listOf("Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor.", "Loop a belt, band, or rope over the ball of your foot. This will be your starting position.", "Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg."), "Hamstrings"),
            Template("Kneeling_Hip_Flexor", "Kneeling Hip Flexor", "Hold & breathe", "Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor. Shift your weight forward until you feel a stretch in your hip.", "Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side.", listOf("Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor.", "Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side."), "Quadriceps, Quadriceps"),
            Template("Dynamic_Chest_Stretch", "Dynamic Chest Stretch", "Hold & breathe", "Stand with your hands together, arms extended directly in front of you. This will be your starting position.", "Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so.", listOf("Stand with your hands together, arms extended directly in front of you. This will be your starting position.", "Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so."), "Chest, Middle back"),
            Template("Spinal_Stretch", "Spinal Stretch", "Hold & breathe", "Sit in a chair so your back is straight and your feet planted on the floor. Interlace your fingers behind your head, elbows out and your chin down.", "Return to upright position and then repeat for your other side.", listOf("Sit in a chair so your back is straight and your feet planted on the floor.", "Interlace your fingers behind your head, elbows out and your chin down.", "Twist your upper body to one side about 3 times as far as you can. Then lean forward and twist your torso to reach your elbow to the floor on the inside of your knee.", "Return to upright position and then repeat for your other side."), "Middle back, Lats, Lower back, Neck, Traps")
        ),
)
